    my ($self, %p) = @_;
    my $names = $p{names} || [];
    my $target = $p{target} || $self->default_target;
    my $all = $p{all};
    my $no_changes = $p{no_changes};
    my @args = @{ $p{args} || [] };
    my @names;
    my $targets = [];
    my $changes = [];
    while (@args) {
        my $arg = shift @args;
        if (my $target_obj = $self->target_from_name($target, $arg)) {
            push @$targets => $target_obj;
            push @names => @{ $target_obj->names };
        } elsif (my $engine = $self->engine_from_name($target, $arg)) {
            my $uri = URI->new("db:$engine:");
            my $target = $self->target_from_name($target, $uri);
            push @$targets => $target;
            push @names => @{ $target->names };
        } elsif (my $change = $self->change_from_name($target, $arg)) {
            push @$changes => $change;
        } elsif (my $uri = $self->uri_from_name($arg)) {
            my $target = $self->target_from_name($target, $uri);
            push @$targets => $target;
            push @names => @{ $target->names };
        } elsif (defined $arg) {
            my $name = shift @names;
            defined $name ? $name->false : push @names => $arg;
        }
    }
    if (@names < @$names) {
        $names = [ @names, @$names ];
    }
    return @$names, $targets, $changes;
}
