    # is not in the project directory.
    if (!$strict && $revert_script !~ /^$FindBin::Bin/) {
        if ($no_prompt) {
            die qq{Revert script not found. Use "--strict" to revert anyway.};
        }
        else {
            my $prompt = qq{Revert script not found: $revert_script\n};
            $prompt .= qq{Would you like to revert to $to_change? (y/n)};
            $prompt .= qq{ [n]} unless $prompt_accept;
            print $prompt;
            my $input = <STDIN>;
            chomp $input;
            if ($input !~ /^y(es)?$/i) {
                die qq{Revert cancelled.};
            }
        }
    }

    # Lock the target.
    $target->acquire_lock($lock_timeout);

    # Revert the change.
    my $reverted;
    try {
        $reverted = $engine->revert($to_change, $vars, $revert_script, $log_only);
    }
    catch {
        my $e = $_;
        my $msg = qq{Unable to revert to $to_change: $e};
        if ($e->isa('App::Sqitch::X::Client') && $e->exit_code == 1) {
            $msg .= qq{\nWould you like to continue reverting? (y/n)};
            $msg .= qq{ [n]} unless $prompt_accept;
            print $msg;
            my $input = <STDIN>;
            chomp $input;
            if ($input !~ /^y(es)?$/i) {
                die qq{Revert cancelled.};
            }
            else {
                redo;
            }
        }
        else {
            die $msg;
        }
    };

    # Update the change log.
    if ($reverted) {
        # Revert the change log.
        $change->revert($to_change);
        # Log the revert.
        $self->sqitch->log->info(qq{Reverted to $to_change.});
    }

    # Release the lock.
    $target->release_lock();

    return $reverted;
}
