use App::Sqitch::X qw(hurl);
use App::Sqitch::Types qw(Str ArrayRef Bool Maybe);
use strict;
use warnings;
use utf8;
use Locale::TextDomain qw(App-Sqitch);
use File::Copy;
use Moo;
use namespace::autoclean;
sub execute {
my $self = shift;
[MASK]
