        my $state_change = $state_changes->{$change_id};
        if ($plan_change && !$state_change) {
            $self->emit_change($change_id, $plan_change, 'missing');
        } elsif (!$plan_change && $state_change) {
            $self->emit_change($change_id, $state_change, 'extra');
        } elsif ($plan_change && $state_change) {
            if ($state_change->{deployed} ne $plan_change->{deployed}) {
                $self->emit_change($change_id, $state_change, 'deployed');
            } elsif ($state_change->{confirmed} ne $plan_change->{confirmed}) {
                $self->emit_change($change_id, $state_change, 'confirmed');
