        my $change_id = $change->{id};
        my $change_plan = $change->{plan};
        my $change_check = $change->{check};

        $self->sqitch->say(q{Verifying }. $change_plan . q{...});

        if ($change_check ne '__VERIFIED__') {
            my $change_dir = File::Spec->catdir($self->sqitch->local_dir, 'change', $change_id);
            my $change_file = File::Spec->catfile($change_dir, 'change');

            $self->sqitch->say(q{Running check script...});
            my $out = eval { $self->sqitch->run_script($change_file, \%vars, \%config) };

            if ($@) {
                hurl verify => qq{Failed to execute check script for change "$change_plan": $@};
