            if ($out !~ /\A\s*\Q$change_check\E\s*\z/) {
                hurl verify => qq{Check script output for change "$change_plan" does not match expected output:};
            }

            $self->sqitch->dbh->do(q{
                UPDATE plan
                SET check = '__VERIFIED__'
                WHERE id = ?
            }, undef, $change_id);

            $self->sqitch->say(q{Successfully verified change "$change_plan"});
        } else {
            $self->sqitch->say(q{Change "$change_plan" is already verified});
        }
    }
}

