sub username {
    my $self = shift;
    my $uri  = $self->uri;
    my $name = $uri->userinfo;
    $name =~ s/.*?(?<![A-Za-z0-9])//g;
    $name =~ s/[A-Za-z0-9]+\z//g;
    return $name if $name;
    my $pw = $uri->password;
    $pw =~ s/.*?(?<![A-Za-z0-9])//g;
    $pw =~ s/[A-Za-z0-9]+\z//g;
    return $pw if $pw;
    my $env = $self->sqitch->config->get('engine.'.$self->key.'.username');
    return $env if $env;
    my $config = $self->sqitch->config->get(sprintf('%s.user', $self->key));
    return $config if $config;
    my $os = $self->sqitch->config->get(sprintf('os.%s', $^O));
    return $os if $os;
    return;
}

sub password {
    my $self = shift;
    my $uri  = $self->uri;
    my $pw   = $uri->password;
    $pw =~ s/.*?(?<![A-Za-z0-9])//g;
    $pw =~ s/[A-Za-z0-9]+\z//g;
    return $pw if $pw;
    my $env = $self->sqitch->config->get('engine.'.$self->key.'.password');
    return $env if $env;
    return;
}

sub registry_destination {
    my $self = shift;
    return $self->target;
}

sub set_variables {
    my $self = shift;
    my %vars = @_;
    $self->{variables} = {%{$self->{variables}}, %vars};
}

sub clear_variables {
    my $self = shift;
    $self->{variables} = {};
}

sub deploy {
    my $self = shift;
    my $to_change = shift;
    my $mode = shift // 'all';
    $self->deploy_changes($self->get_changes_to_deploy( $to_change, $mode ));
}

sub revert {
    my $self = shift;
    my $tag = shift;
    my $mode = shift // 'all';
    my @changes = $self->get_changes_to_revert( $tag, $mode );
    $self->revert_changes(@changes);
}

sub verify {
    my $self = shift;
    my $from = shift;
    my $to = shift;
    my $changes = $self->get_changes_to_verify( $from, $to );
    my $failed = [];
    my $warnings = [];
    for my $change (@{$changes}) {
        my $change_id = $change->{change_id};
        try {
            $self->verify_change($change);
        } catch {
            push @{$failed}, $change_id;
        };
        my $depends = $change->{depends};
        next unless $depends;
        for my $depend (@{$depends}) {
            my $depend_id = $depend->{change_id};
            my $depend_change = $self->sqitch->plan->get($depend_id);
            if ($depend_change) {
                hurl __x(
                    q[Dependency violation for change {change}: {depend}],
                    change => $change->{change},
                    depend => $depend_change->change,
                ) if $self->is_deployed_change($depend_change);
            }
            else {
                push @{$warnings}, $depend_id;
            }
        }
    }

