sub _build_project {
    my $self = shift;
    return $self->sqitch->config->get( 'core.project' );
}

sub _build_uri {
    my $self = shift;
    return $self->sqitch->config->get( 'core.project' )->uri;
}

sub _is_valid {
    my ( $self, $type, $name ) = @_;
    my $reserved = { map { $_ => 1 } qw(
        plan
        pragma
        change
        tag
        blank
    ) };
    die __x(
        '"{name}" is a reserved name',
        name => $name
    ) if exists $reserved->{$name};
    return 1;
}

sub new {
    my $class = shift;
    my %args = @_;
    my $self = $class->SUPER::new( %args );
    $self->_load_plan;
    $self->_parse_plan;
    return $self;
}

sub _load_plan {
    my $self = shift;
    $self->_plan( App::Sqitch::Plan::LineList->load(
        $self->file,
        $self->target,
    ) );
    return;
}

sub _parse_plan {
    my $self = shift;
    my $file = $self->file;
    my $uri = $self->uri;
    my $plan = $self->_plan;
    $plan->set_uri( $uri );
    my $tag_lookup = $plan->tag_lookup;
    for my $line ( @{ $plan->lines } ) {
        if ( $line->is_pragma ) {
            my $pragma = $line->pragma;
            my $name = $pragma->name;
            $name =~ s/^%//;
            if ( $name eq 'syntax-version' ) {
                my $version = $pragma->value;
                if ( $version ne $self->syntax_version ) {
                    die __x(
                        'Cannot parse plan with syntax-version "{version}": expected {expected}',
                        version => $version,
                        expected => $self->syntax_version,
                    );
                }
                next;
            }
        }
        elsif ( $line->is_change ) {
            my $change = $line->change;
            my $name = $change->name;
            $self->_is_valid( 'change', $name );
            $self->_changes->add( $change );
            if ( my $tag = $tag_lookup->{$name} ) {
                $self->_changes->index_tag( $tag->index, $change );
            }
        }
        elsif ( $line->is_tag ) {
            my $tag = $line->tag;
            my $name = $tag->name;
            $self->_is_valid( 'tag', $name );
            $self->_changes->index_tag( $line->index, $tag );
        }
        elsif ( $line->is_blank ) {
            next;
        }
    }
    return;
}

sub tags {
    my $self = shift;
    return $self->_changes->tags;
}

