sub index_of {
    my ( $self, $key ) = @_;

    # Look for non-deployed symbolic references.
    if ( my $offset = _offset $key ) {
        my $idx = $self->_index_of( $key ) // return undef;
        $idx += $offset;
        return $idx < 0 ? undef : $idx > $#{ $self->{list} } ? undef : $idx;
    } else {
        return $self->_index_of( $key );
